import{_ as t,a,o as d,a4 as o}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Auth & Context mapping","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-graphql-mapping/shop/auth-context.md","filePath":"api/rest-graphql-mapping/shop/auth-context.md","lastUpdated":1784902076000}'),r={name:"api/rest-graphql-mapping/shop/auth-context.md"};function n(s,e,c,h,i,l){return d(),a("div",null,e[0]||(e[0]=[o('<h1 id="auth-context-mapping" tabindex="-1">Auth &amp; Context mapping <a class="header-anchor" href="#auth-context-mapping" aria-label="Permalink to &quot;Auth &amp; Context mapping&quot;">​</a></h1><p>Authentication and the locale/currency/channel context are <strong>identical</strong> across REST and GraphQL — same headers, same tokens. Only the catalog filter/sort syntax differs (see <a href="/api/rest-graphql-mapping/shop/catalog.html">Catalog</a>).</p><h2 id="authentication-headers" tabindex="-1">Authentication headers <a class="header-anchor" href="#authentication-headers" aria-label="Permalink to &quot;Authentication headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Storefront key</td><td><code>X-STOREFRONT-KEY</code> header</td><td><code>X-STOREFRONT-KEY</code> header (same)</td></tr><tr><td>Customer / guest-cart Bearer</td><td><code>Authorization: Bearer &lt;token&gt;</code></td><td><code>Authorization: Bearer &lt;token&gt;</code> (same)</td></tr><tr><td>GraphQL endpoint</td><td>—</td><td><code>POST /api/graphql</code> (shop)</td></tr></tbody></table><ul><li><strong>Which login field is the Bearer:</strong> use <code>token</code> (format <code>&lt;id&gt;|&lt;secret&gt;</code>) — <strong>never</strong> <code>apiToken</code>. <code>apiToken</code> is a legacy field; sending it returns <code>Unauthenticated</code>.</li><li><strong>Guest vs customer:</strong> a guest cart/checkout call sends the <strong>cart token</strong> as the Bearer; a logged-in call sends the <strong>customer token</strong>. Both use the same <code>Authorization: Bearer</code> header.</li><li>Credential lifetimes and the &quot;no refresh token&quot; rule: <a href="/api/authentication.html#credential-lifetimes">Authentication</a>.</li></ul><h2 id="context-headers" tabindex="-1">Context headers <a class="header-anchor" href="#context-headers" aria-label="Permalink to &quot;Context headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Locale</td><td><code>X-LOCALE</code> header (or <code>?locale=</code> on catalog)</td><td><code>X-LOCALE</code> header</td></tr><tr><td>Currency</td><td><code>X-CURRENCY</code> header</td><td><code>X-CURRENCY</code> header</td></tr><tr><td>Channel</td><td><code>X-CHANNEL</code> header (or <code>?channel=</code> on catalog)</td><td><code>X-CHANNEL</code> header</td></tr></tbody></table><p>Omitting a context header (or passing an unknown value) falls back to the channel default. Discover valid values from <a href="/api/rest-api/shop/locales/get-locales.html">Locales</a> and <a href="/api/rest-api/shop/channels/get-channels.html">Channels</a> (a channel lists its allowed currencies and locales) — <strong>not</strong> the Countries endpoint (countries are for address forms).</p><h2 id="response-shape-differences" tabindex="-1">Response-shape differences <a class="header-anchor" href="#response-shape-differences" aria-label="Permalink to &quot;Response-shape differences&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Collection wrapper</td><td>flat JSON array + <code>X-Total-Count</code> / <code>X-Page</code> headers</td><td>Relay connection — <code>edges { node }</code> + <code>pageInfo</code></td></tr><tr><td>Record id</td><td>numeric <code>id</code></td><td><code>id</code> is an <strong>IRI</strong> string; <code>_id</code> is the numeric id — <a href="/api/graphql-api/identifiers.html">Identifiers</a></td></tr><tr><td>Money fields</td><td>numeric</td><td>may serialise as strings — render the <code>formatted*</code> fields either way</td></tr><tr><td>Action results</td><td>JSON body with <code>success</code> / <code>message</code></td><td>select the payload&#39;s <strong>value field</strong> (<code>cartId</code>, <code>orderId</code>, <code>success</code>) — not <code>id</code></td></tr></tbody></table>',10)]))}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
